#include "textflag.h"

TEXT ·aesRoundAsm(SB),NOSPLIT,$0-16
	MOVQ block+0(FP), AX
	MOVQ roundKey+8(FP), BX
	MOVOU (AX), X0
	MOVOU (BX), X1
	AESENC X1, X0
	MOVOU X0, (AX)
	PXOR X0, X0
	PXOR X1, X1
	XORQ AX, AX
	XORQ BX, BX
	RET

TEXT ·aesRoundVexAsm(SB),NOSPLIT,$0-16
	MOVQ block+0(FP), AX
	MOVQ roundKey+8(FP), BX
	VMOVDQU (AX), X0
	VAESENC (BX), X0, X0
	VMOVDQU X0, (AX)
	VPXOR X0, X0, X0
	XORQ AX, AX
	XORQ BX, BX
	RET

TEXT ·aesFinalRoundAsm(SB),NOSPLIT,$0-16
	MOVQ block+0(FP), AX
	MOVQ roundKey+8(FP), BX
	MOVOU (AX), X0
	MOVOU (BX), X1
	AESENCLAST X1, X0
	MOVOU X0, (AX)
	PXOR X0, X0
	PXOR X1, X1
	XORQ AX, AX
	XORQ BX, BX
	RET

TEXT ·aesFinalRoundVexAsm(SB),NOSPLIT,$0-16
