TEXT ·aes128EncryptBlockAsm(SB),NOSPLIT,$0-24
	MOVQ rk+0(FP), AX
	MOVQ dst+8(FP), DX
	MOVQ src+16(FP), CX
	MOVOU (CX), X0
	MOVOU 0(AX), X1
	PXOR X1, X0
	MOVOU 16(AX), X1
	AESENC X1, X0
	MOVOU 32(AX), X1
	AESENC X1, X0
	MOVOU 48(AX), X1
	AESENC X1, X0
	MOVOU 64(AX), X1
	AESENC X1, X0
	MOVOU 80(AX), X1
	AESENC X1, X0
	MOVOU 96(AX), X1
	AESENC X1, X0
	MOVOU 112(AX), X1
	AESENC X1, X0
	MOVOU 128(AX), X1
	AESENC X1, X0
	MOVOU 144(AX), X1
	AESENC X1, X0
	MOVOU 160(AX), X1
	AESENCLAST X1, X0
	MOVOU X0, (DX)
	PXOR X0, X0
	PXOR X1, X1
	XORQ AX, AX
	XORQ CX, CX
	XORQ DX, DX
	RET

