	VBROADCASTI32X4 144(AX), Z1
	VAESENC Z1, Z0, Z0
	VBROADCASTI32X4 160(AX), Z1
	VAESENCLAST Z1, Z0, Z0
	VMOVDQU64 Z0, (DX)
	VPXORD X0, X0, X0
	VPXORD X1, X1, X1
	XORQ AX, AX
	XORQ CX, CX
	XORQ DX, DX
	VZEROUPPER
	RET

